from rest_framework import viewsets, permissions
from .models import ZeroDayVulnerabilityReport
from .serializers import ZeroDayVulnerabilityReportSerializer

class IsReporterOrSecurityTriager(permissions.BasePermission):
    def has_object_permission(self, request, view, obj):
        is_reporter = obj.researcher == request.user
        is_triager = request.user.groups.filter(name="SecurityTriageTeam").exists()
        return is_reporter or is_triager

class VulnerabilityDisclosureViewSet(viewsets.ModelViewSet):
    serializer_class = ZeroDayVulnerabilityReportSerializer
    permission_classes = [permissions.IsAuthenticated, IsReporterOrSecurityTriager]

    def get_queryset(self):
        user = self.request.user
        if user.groups.filter(name="SecurityTriageTeam").exists():
            return ZeroDayVulnerabilityReport.objects.all()
        return ZeroDayVulnerabilityReport.objects.filter(researcher=user)
